input.command:
CNF="$HOME/Desktop/CHcode/.claude/database/my.cnf.prod"
# 口径 spot-check：session_duration 是否仍有 daily bucket0；metrics 分区形状；page_stay 行数
mysql --defaults-file="$CNF" -e "
-- session_duration T-1 grains
SELECT dt, stat_grain, duration_bucket, SUM(session_cnt) sc, SUM(user_cnt) uc, SUM(bounce_cnt) bc
FROM dws.dws_session_duration_user_d
WHERE dt='2026-09-07'
GROUP BY 1,2,3 ORDER BY 2,3 LIMIT 20;

SELECT 'page_stay' t, COUNT(*) c, COUNT(DISTINCT dt) d, MIN(dt), MAX(dt) FROM dwd.dwd_app_page_stay_d;
SELECT 'dashboard_ext_exists' t, COUNT(*) FROM information_schema.tables WHERE table_schema='dws' AND table_name LIKE '%attribution_dashboard%';
DESC dws.dws_register_attribution_metrics_d_d;
" 2>&1 | head -80
